// Nivel 4: M17 (robot que evita obstáculos), M18 (seguidor de línea) y M19 (carro a control remoto).
window.CURSO.modulos.push(
{id: "M17", n: 4, t: "Proyecto: robot que evita obstáculos", d: "Construye paso a paso un robot móvil de dos ruedas que explora una habitación sin chocar, con sensor ultrasónico sobre un servo de barrido.", dep: ["M12", "M14", "M15", "M16"],
 obj: ["Diseñar un robot móvil completo con su lista de materiales.", "Montar chasis, motores, driver, batería y sensores.", "Programar un comportamiento de evasión como máquina de estados.", "Probar y mejorar el robot con criterios medibles."],
 prac: ["Montaje completo del robot 2WD.", "Programa de evasión con barrido del servo."],
 mat: ["Chasis 2WD con 2 motorreductores y rueda loca", "Arduino Uno o Nano", "Driver TB6612FNG o L298N", "Sensor HC-SR04 y soporte", "Servo SG90", "2 celdas 18650 en porta-baterías con interruptor (o 6 pilas AA)", "Convertidor buck (si hace falta)", "Zumbador, LED, cables, tornillos M3"],
 pj: {t: "Entrega: robot explorador", h: 1, d: "Presenta tu robot funcionando en un recorrido con obstáculos y su documentación.",
  pasos: ["Prepara un recorrido de al menos 2 × 2 m con 5 obstáculos de distintos tamaños (cajas, botellas, una silla).", "Haz 3 pruebas de 2 minutos y cuenta los choques.", "Graba un vídeo de la mejor prueba.", "Entrega el esquema, la lista de materiales con costes, el código comentado y el diagrama de estados.", "Escribe qué mejorarías en una segunda versión."],
  crit: ["El robot funciona de forma autónoma durante 2 minutos.", "Choca como máximo una vez por prueba.", "Usa el servo para elegir la dirección más libre.", "El código es una máquina de estados sin delay() largos.", "La documentación está completa (esquema, materiales, código, diagrama)."],
  rub: [["Funcionamiento autónomo y número de choques", 35], ["Calidad del montaje (firme, ordenado, seguro)", 20], ["Código (estructura, comentarios, sin bloqueos)", 25], ["Documentación y propuestas de mejora", 20]]},
 L: [
 {t: "Diseño y lista de materiales", h: 1, s: 1, p: "Antes de comprar nada, ¿qué debe hacer exactamente tu robot?",
  o: ["Definir los requisitos del robot evasor.", "Elaborar el diagrama de bloques, la lista de materiales y el presupuesto de energía."],
  x: ["Aplicamos el **método de diseño** (M02) a nuestro primer robot completo.",
   "### Requisitos",
   "- Moverse de forma **autónoma** por una habitación durante al menos 20 minutos.\n- **Detectar obstáculos** a 25 cm o más y no chocar con objetos de más de 10 cm de alto.\n- Elegir **hacia dónde girar** mirando a ambos lados (servo de barrido).\n- Tener un **interruptor** de encendido y un **botón** de inicio.\n- Coste aproximado: 30–50 USD.",
   "### Diagrama de bloques",
   "- **Energía:** 2 × 18650 (7,4 V) → interruptor y fusible → driver de motores (VM) y entrada VIN del Arduino (o buck a 5 V).\n- **Controlador:** Arduino Uno/Nano.\n- **Sensores:** HC-SR04 sobre un servo SG90 (que gira para mirar a izquierda, centro y derecha).\n- **Actuadores:** 2 motorreductores TT a través del TB6612FNG; zumbador y LED de estado.",
   "### Asignación de pines (ejemplo)",
   "- Motor izquierdo: AIN1 = 7, AIN2 = 8, PWMA = 5. Motor derecho: BIN1 = 12, BIN2 = 13, PWMB = 6. STBY = 4.\n- Servo: pin 10 (la biblioteca Servo usa el temporizador de los pines 9 y 10: no uses PWM de motores en ellos).\n- HC-SR04: Trig = A0, Echo = A1 (los pines analógicos sirven como digitales).\n- Botón: pin 2 (INPUT_PULLUP). Zumbador: pin 3. LED: pin 11.",
   "### Presupuesto de energía (M10)",
   "Arduino ~50 mA + motores ~2 × 200 mA + servo ~150 mA en movimiento + sensor 15 mA ≈ **600 mA medios**; picos de unos 2,5 A. Con 2 × 18650 de 2500 mAh: 2500 × 0,8 / 600 ≈ **3,3 horas**. El servo y el sensor se alimentan a 5 V desde el Arduino (o mejor desde un buck), y los motores directamente de la batería a través del driver.",
   "Antes de montar, **simula** la lógica en Wokwi con el sensor y un servo: te ahorrará tiempo."],
  g: "robot2wd", k: "Requisitos medibles → diagrama de bloques → asignación de pines → presupuesto de energía → lista de materiales. Todo antes de montar.",
  er: ["Asignar el PWM de un motor al pin 9 o 10 mientras se usa la biblioteca Servo.", "No calcular la energía y quedarse sin batería en minutos."],
  q: [["¿Qué sensor usa el robot para ver obstáculos?", ["PIR", "HC-SR04", "DHT22", "LDR"], 1, "El ultrasonido mide la distancia."],
   ["¿Para qué sirve el servo en este robot?", ["Para mover las ruedas", "Para girar el sensor y mirar a los lados", "Para cargar la batería", "Para el WiFi"], 1, "Permite elegir la dirección más libre."],
   ["¿Qué pines conviene evitar para el PWM de motores si usas la biblioteca Servo en el Uno?", ["2 y 3", "9 y 10", "A0 y A1", "12 y 13"], 1, "Servo usa el temporizador de esos pines."],
   ["Consumo medio de 600 mA y batería de 2500 mAh (factor 0,8). ¿Autonomía? (en h)", {n: 3.33, tol: 0.02, u: "h"}, null, "2500 × 0,8 / 600 ≈ 3,3 h."],
   ["¿Qué se hace antes de montar el robot?", ["Comprar al azar", "Definir requisitos, diagrama, pines y energía", "Programar sin probar", "Pintarlo"], 1, "Es el método de diseño."]]},
 {t: "Montaje del chasis y los motores", h: 2, s: 1, p: "¿Por qué tantos robots se desmontan solos tras unos minutos de funcionamiento?",
  o: ["Montar el chasis 2WD de forma firme y ordenada.", "Preparar los motores con cables, condensadores y una distribución correcta del peso."],
  x: ["### Preparar los motores",
   "- **Suelda los cables** a los terminales de cada motor (rojo y negro, unos 15 cm). Los terminales de los motores TT son frágiles: no los dobles muchas veces.\n- Suelda un **condensador cerámico de 100 nF** entre los dos terminales de cada motor (reduce el ruido, M14).\n- Protege las soldaduras con **termorretráctil** o un punto de silicona y sujeta los cables al cuerpo del motor con una brida para que no tiren de los terminales.",
   "### Montar el chasis",
   "- **1.** Fija los motores al chasis con sus soportes y tornillos largos. Comprueba que quedan **paralelos** y bien apretados: un motor torcido hace que el robot no vaya recto.\n- **2.** Coloca las **ruedas** a presión en el eje (con cuidado de no forzar la reductora). Si llevan disco de encoder, colócalo antes.\n- **3.** Monta la **rueda loca** en la parte delantera o trasera con separadores, de forma que el chasis quede **horizontal**.\n- **4.** Coloca el **porta-baterías** lo más bajo y centrado posible, cerca del eje de las ruedas. Fíjalo con tornillos, velcro o bridas: no debe moverse.\n- **5.** Atornilla el **Arduino** y el **driver** con separadores, dejando accesibles el puerto USB y el interruptor.\n- **6.** Monta el **servo** en la parte delantera con su soporte, y el **sensor ultrasónico** sobre él con un soporte impreso, de plástico o de cartón rígido. Centra el servo en 90° (con un pequeño programa) **antes** de fijar el soporte, para que «mirar al frente» sea 90°.",
   "### Orden y accesibilidad",
   "Pasa los cables por los agujeros del chasis, agrúpalos con bridas y deja la batería, el interruptor y el USB fáciles de alcanzar. Un montaje ordenado es más fiable y mucho más fácil de reparar.",
   "### Prueba de sacudida",
   "Cuando termines, coge el robot y sacúdelo suavemente: no debe moverse ni sonar nada. Haz la prueba de tirón en los cables (M06)."],
  pr: {m: ["kit de chasis 2WD", "cautín, estaño, termorretráctil", "2 condensadores de 100 nF", "destornillador, bridas, separadores M3"], p: ["Suelda cables y condensadores a los motores.", "Monta motores, ruedas y rueda loca.", "Fija batería, Arduino, driver, servo y sensor.", "Centra el servo en 90° antes de colocar el soporte del sensor.", "Haz la prueba de sacudida y la de tirón."], e: "Un chasis firme, horizontal y ordenado, listo para cablear.", sim: "Si aún no tienes el kit, diseña la distribución en papel o en Tinkercad 3D."},
  sg: "Usa gafas al soldar y al cortar bridas y patas. No fuerces los ejes de los motores TT: su reductora de plástico se rompe.",
  er: ["Motores flojos o torcidos.", "Batería suelta que se desplaza y cambia el equilibrio."],
  q: [["¿Para qué se suelda un condensador de 100 nF en cada motor?", ["Para que gire más rápido", "Para reducir el ruido eléctrico", "Para invertir el giro", "Para medir la velocidad"], 1, "Filtra los picos de las escobillas."],
   ["¿Por qué deben quedar los motores paralelos?", ["Por estética", "Para que el robot vaya recto", "Para que no se calienten", "Da igual"], 1, "Un motor torcido desvía el robot."],
   ["¿Dónde se coloca la batería?", ["Arriba del todo", "Baja y centrada cerca del eje de las ruedas", "Colgando por detrás", "Sobre el sensor"], 1, "Mejora la estabilidad y la tracción."],
   ["¿Qué se hace con el servo antes de fijar el soporte del sensor?", ["Quitarle los engranajes", "Centrarlo en 90°", "Pintarlo", "Desconectarlo"], 1, "Así 90° equivale a mirar al frente."],
   ["¿Qué comprueba la prueba de sacudida?", ["La batería", "Que nada está suelto", "El código", "El WiFi"], 1, "Las piezas flojas se notan enseguida."]]},
 {t: "Cableado: driver, sensor y batería", h: 1.5, s: 1, p: "¿Qué tiene que pasar para que encender el robot no sea un momento de tensión?",
  o: ["Cablear la alimentación, el driver, el servo y el sensor siguiendo el esquema.", "Comprobar la instalación antes de alimentarla."],
  x: ["Sigue el esquema y el orden de **integración** del M16: alimentación primero, luego cada subsistema, probando después de cada paso.",
   "### 1. Alimentación",
   "- Batería (+) → **fusible** (2–3 A) → **interruptor** → riel positivo de potencia.\n- Riel positivo de potencia → **VM** del TB6612 (o 12V del L298N) y → **VIN** del Arduino (7–12 V). Alternativa recomendada: un **buck a 5 V** que alimente el pin 5V del Arduino, el servo y el sensor, para que los picos del servo no afecten al Arduino.\n- Batería (−) → GND del driver y GND del Arduino: **tierra común**.\n- Antes de conectar nada más, enciende y **mide**: unos 7–8,4 V en VM y el Arduino encendido.",
   "### 2. Driver de motores",
   "- **VCC** del TB6612 a 5V del Arduino; **STBY** a su pin (o a 5V).\n- AIN1, AIN2, PWMA, BIN1, BIN2, PWMB a los pines asignados en la lección 1.\n- AO1/AO2 al motor izquierdo y BO1/BO2 al derecho.\n- **Prueba:** con las ruedas en el aire, carga un programa que mueva cada motor por separado adelante y atrás. Si un motor gira al revés, intercambia sus cables.",
   "### 3. Servo",
   "- Marrón a GND, rojo a 5 V (del buck o del Arduino), naranja al pin 10.\n- Un **condensador de 470 µF** entre 5 V y GND cerca del servo.\n- **Prueba:** barrido de 30° a 150°.",
   "### 4. Sensor ultrasónico",
   "- VCC a 5 V, GND, Trig a A0, Echo a A1. Deja los cables con holgura para que el servo pueda girar sin tirar de ellos.\n- **Prueba:** imprime la distancia **con los motores girando**: si aparecen lecturas absurdas, revisa la tierra común, aleja los cables de los motores y añade condensadores.",
   "### 5. Botón, zumbador y LED",
   "Botón entre el pin 2 y GND; zumbador en el pin 3; LED con su resistencia en el pin 11. **Prueba** cada uno.",
   "Documenta el cableado con una foto y anota cualquier cambio respecto al esquema."],
  c: {l: "cpp", t: "// Programa de diagnóstico: prueba cada motor por separado\nconst int AIN1 = 7, AIN2 = 8, PWMA = 5, BIN1 = 12, BIN2 = 13, PWMB = 6, STBY = 4;\n\nvoid motor(int in1, int in2, int pwm, int v) {\n  digitalWrite(in1, v > 0); digitalWrite(in2, v < 0); analogWrite(pwm, abs(v));\n}\n\nvoid setup() {\n  int p[] = {AIN1, AIN2, PWMA, BIN1, BIN2, PWMB, STBY};\n  for (int x : p) pinMode(x, OUTPUT);\n  digitalWrite(STBY, HIGH);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  Serial.println(\"Izquierdo adelante\");  motor(AIN1, AIN2, PWMA, 180);  delay(1500); motor(AIN1, AIN2, PWMA, 0);\n  Serial.println(\"Izquierdo atrás\");     motor(AIN1, AIN2, PWMA, -180); delay(1500); motor(AIN1, AIN2, PWMA, 0);\n  Serial.println(\"Derecho adelante\");    motor(BIN1, BIN2, PWMB, 180);  delay(1500); motor(BIN1, BIN2, PWMB, 0);\n  Serial.println(\"Derecho atrás\");       motor(BIN1, BIN2, PWMB, -180); delay(1500); motor(BIN1, BIN2, PWMB, 0);\n  delay(2000);\n}"},
  sg: "Coloca el fusible junto a la batería y prueba los motores siempre con las ruedas en el aire la primera vez. Desconecta la batería antes de cambiar cables.",
  er: ["Olvidar la tierra común entre el driver y el Arduino.", "Cables del sensor demasiado tensos que se sueltan al girar el servo."],
  q: [["¿Qué se cablea y prueba primero?", ["El sensor", "La alimentación", "El servo", "El zumbador"], 1, "Es la base de todo."],
   ["Un motor gira al revés en la prueba. ¿Qué haces?", ["Cambias el Arduino", "Intercambias los dos cables de ese motor", "Cambias la batería", "Nada"], 1, "Así se invierte su polaridad."],
   ["¿Por qué alimentar el servo desde un buck en lugar del Arduino?", ["Para que gire al revés", "Para que sus picos no reinicien el Arduino", "Porque el servo usa 12 V", "No hay diferencia"], 1, "Separa los consumos."],
   ["¿Cuándo se prueba el sensor ultrasónico?", ["Solo con los motores apagados", "También con los motores girando", "Nunca", "Solo de noche"], 1, "El ruido de los motores puede afectarle."],
   ["¿Dónde va el fusible?", ["Junto a la batería, en el positivo", "En el cable del sensor", "En el GND del servo", "En el USB"], 0, "Protege todo el cableado."]]},
 {t: "Programa base: avanzar, detectar y girar", h: 1.5, s: 1, p: "¿Cuál es el programa más sencillo que hace que tu robot no choque?",
  o: ["Programar el comportamiento básico de evasión.", "Organizarlo como máquina de estados sin bloqueos largos."],
  x: ["Empezamos con una versión sencilla **con el sensor mirando al frente** (servo fijo en 90°). El diagrama de estados:",
   "- **ESPERA:** motores parados hasta que se pulsa el botón → AVANZAR.\n- **AVANZAR:** ambas ruedas adelante. Si la distancia < 25 cm → RETROCEDER.\n- **RETROCEDER:** ambas ruedas atrás durante 300 ms → GIRAR.\n- **GIRAR:** girar en el sitio hacia un lado (alternando o al azar) durante unos 400 ms → AVANZAR.",
   "### Detalles importantes",
   "- La distancia se lee cada **50 ms** y se filtra con la **mediana** de 3–5 lecturas (M12) para que una lectura falsa no provoque un frenazo.\n- Las lecturas de 0 (sin eco) se tratan como «camino libre», pero si se repiten mucho, conviene parar: puede que el sensor esté desconectado.\n- La **velocidad** de avance se elige según la distancia de reacción: a más velocidad, mayor distancia de frenado. Empieza con PWM 150–180.\n- El botón vuelve a ESPERA en cualquier momento: es tu **parada de emergencia**.",
   "Este programa ya hace que el robot recorra la habitación, aunque a veces elegirá mal el lado de giro y quedará atascado en esquinas. Lo mejoraremos en las siguientes lecciones."],
  c: {l: "cpp", t: "// Robot evasor: versión base con máquina de estados\nconst int AIN1 = 7, AIN2 = 8, PWMA = 5, BIN1 = 12, BIN2 = 13, PWMB = 6, STBY = 4;\nconst int TRIG = A0, ECHO = A1, BOTON = 2, ZUMBADOR = 3;\nconst int DIST_MIN = 25, VEL = 170;\n\nenum Estado { ESPERA, AVANZAR, RETROCEDER, GIRAR };\nEstado estado = ESPERA;\nunsigned long tEstado = 0, tSensor = 0;\nfloat distancia = 100;\nint sentidoGiro = 1;\n\nvoid motor(int a, int b, int p, int v) { digitalWrite(a, v > 0); digitalWrite(b, v < 0); analogWrite(p, abs(v)); }\nvoid mover(int izq, int der) { motor(AIN1, AIN2, PWMA, izq); motor(BIN1, BIN2, PWMB, der); }\nvoid cambiarA(Estado e) { estado = e; tEstado = millis(); }\n\nfloat medir() {\n  digitalWrite(TRIG, LOW); delayMicroseconds(2);\n  digitalWrite(TRIG, HIGH); delayMicroseconds(10); digitalWrite(TRIG, LOW);\n  unsigned long t = pulseIn(ECHO, HIGH, 25000);\n  return t == 0 ? 400 : t * 0.0343 / 2;        // sin eco = lejos\n}\n\nvoid setup() {\n  int p[] = {AIN1, AIN2, PWMA, BIN1, BIN2, PWMB, STBY, TRIG};\n  for (int x : p) pinMode(x, OUTPUT);\n  pinMode(ECHO, INPUT); pinMode(BOTON, INPUT_PULLUP);\n  digitalWrite(STBY, HIGH);\n}\n\nvoid loop() {\n  if (millis() - tSensor >= 50) { tSensor = millis(); distancia = medir(); }\n  bool boton = digitalRead(BOTON) == LOW;\n  unsigned long t = millis() - tEstado;\n\n  switch (estado) {\n    case ESPERA:\n      mover(0, 0);\n      if (boton) { tone(ZUMBADOR, 880, 150); delay(400); cambiarA(AVANZAR); }\n      break;\n    case AVANZAR:\n      mover(VEL, VEL);\n      if (distancia < DIST_MIN) cambiarA(RETROCEDER);\n      if (boton) { delay(400); cambiarA(ESPERA); }\n      break;\n    case RETROCEDER:\n      mover(-VEL, -VEL);\n      if (t > 300) { sentidoGiro = random(2) ? 1 : -1; cambiarA(GIRAR); }\n      break;\n    case GIRAR:\n      mover(VEL * sentidoGiro, -VEL * sentidoGiro);\n      if (t > 400) cambiarA(AVANZAR);\n      break;\n  }\n}"},
  pr: {m: ["robot montado y cableado", "obstáculos (cajas, libros)"], p: ["Carga el programa base y prueba primero con el robot en el aire.", "Pruébalo en el suelo con una pared delante.", "Ajusta DIST_MIN y VEL hasta que no choque.", "Añade el filtro de mediana a la distancia.", "Cuenta los choques en 2 minutos de recorrido."], e: "El robot recorre la habitación y gira al encontrar obstáculos.", sim: "Prueba la lógica en Wokwi con un HC-SR04 y LED en lugar de motores."},
  sg: "Prueba en el suelo, lejos de escaleras. El botón debe detener el robot en cualquier estado.",
  er: ["Una velocidad demasiado alta para la distancia de reacción.", "Reaccionar a una sola lectura falsa del sensor."],
  q: [["¿Qué estado sigue a RETROCEDER?", ["ESPERA", "AVANZAR", "GIRAR", "RETROCEDER otra vez"], 2, "Tras retroceder, gira para buscar otro camino."],
   ["¿Por qué se filtra la distancia con la mediana?", ["Para ir más rápido", "Para que una lectura falsa no provoque un frenazo", "Para ahorrar batería", "Por estética"], 1, "La mediana elimina picos aislados."],
   ["¿Qué ocurre si se aumenta mucho la velocidad sin cambiar DIST_MIN?", ["Nada", "El robot puede chocar antes de reaccionar", "El robot se para", "El sensor mide mejor"], 1, "Necesita más distancia para frenar y girar."],
   ["¿Qué función tiene el botón durante el recorrido?", ["Cambiar el color", "Parada de emergencia (volver a ESPERA)", "Cargar la batería", "Ninguna"], 1, "Siempre debe poder detenerse el robot."],
   ["En el código, ¿qué devuelve medir() si no hay eco?", ["0", "400 (camino libre)", "−1", "Un error"], 1, "Se interpreta como que no hay obstáculo cerca."]]},
 {t: "Radar: barrido con el servo", h: 1.5, p: "¿Cómo decide el robot si es mejor girar a la izquierda o a la derecha?",
  o: ["Medir distancias en varias direcciones moviendo el servo.", "Elegir la dirección más libre y girar hacia ella."],
  x: ["El robot de la lección anterior gira al azar. Con el **servo**, puede **mirar antes de decidir**: es como una persona que, al encontrar una pared, mira a los dos lados antes de girar.",
   "### El nuevo estado MIRAR",
   "Cuando detecta un obstáculo, el robot **se detiene** y pasa al estado **MIRAR**:",
   "- **1.** Gira el servo a la **izquierda** (por ejemplo, 150°), espera unos 250 ms a que llegue y mide.\n- **2.** Gira a la **derecha** (30°), espera y mide.\n- **3.** Vuelve al **centro** (90°).\n- **4.** Elige el lado con **más distancia**. Si ambos están bloqueados (menos de 25 cm), retrocede más y gira 180°.",
   "### Mapa de distancias",
   "Una versión más completa mide **cada 30°** (de 30° a 150°: 5 direcciones) y guarda las distancias en un **arreglo**. Luego elige el ángulo con mayor distancia y gira un tiempo proporcional (calibrado en el M14) para orientarse hacia él. Así obtienes un pequeño **radar**: puedes enviar los datos por serie y dibujarlos en la computadora.",
   "### Sin bloquear",
   "Las esperas del servo se hacen con `millis()` dentro del estado MIRAR (sub-pasos: mover a la izquierda, esperar, medir, mover a la derecha…), de modo que el botón de parada sigue funcionando. Como el robot está parado mientras mira, un `delay` corto también es aceptable en una primera versión.",
   "### Mirar mientras avanza",
   "Una mejora avanzada: mientras avanza, el servo oscila suavemente entre 60° y 120° para vigilar también los laterales y detectar obstáculos en diagonal antes de llegar a ellos."],
  c: {l: "cpp", t: "// Estado MIRAR: elige el lado más libre (versión sencilla con esperas cortas)\n#include <Servo.h>\nServo cuello;   // en setup(): cuello.attach(10); cuello.write(90);\n\nfloat medirEn(int angulo) {\n  cuello.write(angulo);\n  delay(300);                    // espera a que el servo llegue (robot parado)\n  float suma = 0;\n  for (int i = 0; i < 3; i++) { suma += medir(); delay(30); }\n  return suma / 3;\n}\n\nint elegirSentido() {            // 1 = derecha, -1 = izquierda, 0 = media vuelta\n  float izq = medirEn(150);\n  float der = medirEn(30);\n  cuello.write(90);\n  if (izq < DIST_MIN && der < DIST_MIN) return 0;\n  return (der >= izq) ? 1 : -1;\n}\n\n// En la máquina de estados:\n// case AVANZAR: if (distancia < DIST_MIN) { mover(0,0); cambiarA(MIRAR); } break;\n// case MIRAR: { int s = elegirSentido();\n//               if (s == 0) { sentidoGiro = 1; tGiro = 800; }   // media vuelta\n//               else { sentidoGiro = s; tGiro = 400; }\n//               cambiarA(GIRAR); } break;"},
  pr: {m: ["robot completo"], p: ["Añade el estado MIRAR y la función elegirSentido().", "Coloca el robot frente a una esquina y comprueba que gira hacia el lado libre.", "Implementa la versión de 5 direcciones con un arreglo.", "Envía por serie «ángulo,distancia» y dibújalo como radar (en el trazador o en una hoja de cálculo)."], e: "El robot gira siempre hacia el lado más despejado y sale de las esquinas.", sim: "Wokwi con un servo y un HC-SR04 controlado manualmente."},
  er: ["Medir antes de que el servo haya llegado a su posición.", "No contemplar el caso en que ambos lados están bloqueados."],
  q: [["¿Qué hace el robot en el estado MIRAR?", ["Avanza rápido", "Se detiene y mide la distancia a ambos lados", "Carga la batería", "Apaga el sensor"], 1, "Mira antes de decidir."],
   ["Izquierda: 80 cm; derecha: 35 cm. ¿Hacia dónde gira?", ["Izquierda", "Derecha", "Media vuelta", "No gira"], 0, "Elige el lado con más distancia."],
   ["Ambos lados a menos de 25 cm. ¿Qué hace?", ["Avanza", "Media vuelta", "Se apaga", "Gira a la izquierda siempre"], 1, "Está en un callejón sin salida."],
   ["¿Por qué esperar unos 300 ms tras mover el servo?", ["Para ahorrar batería", "Para que llegue a la posición antes de medir", "Por estética", "No hace falta"], 1, "Si no, mide en una dirección intermedia."],
   ["¿Qué estructura de datos guarda las distancias de 5 direcciones?", ["Un arreglo", "Un booleano", "Un char", "Un switch"], 0, "Una posición por ángulo."]]},
 {t: "Pruebas y mejoras", h: 1.5, p: "Tu robot funciona… ¿cómo sabes si funciona bien?",
  o: ["Probar el robot con un protocolo y medir su rendimiento.", "Aplicar mejoras de comportamiento, mecánica y energía."],
  x: ["### Protocolo de prueba",
   "Define un **escenario fijo**: un área de 2 × 2 m con 5 obstáculos (incluye uno bajo, uno estrecho como la pata de una silla y uno blando). Haz **3 pruebas de 2 minutos** y anota en una tabla: choques, atascos (más de 5 s sin avanzar), área recorrida y batería al final. Cambia **una sola cosa** entre series de pruebas y compara.",
   "### Problemas típicos y soluciones",
   "- **Choca con patas de sillas o cables:** el cono del ultrasonido no los ve bien. Añade **sensores IR de obstáculo** a los lados o un **parachoques** con finales de carrera.\n- **Se atasca en esquinas:** usa el barrido del servo; si lleva más de X giros seguidos, haz una media vuelta.\n- **Choca con objetos blandos:** el ultrasonido no los detecta; un VL53L0X o un parachoques ayudan.\n- **Va torcido:** factor de corrección por motor o encoders con PID (M16).\n- **Reacciona tarde:** baja la velocidad o reduce el tiempo entre lecturas; elimina delays.\n- **Se reinicia:** revisa la alimentación (M10, M25): buck para la lógica, condensadores, batería cargada.",
   "### Mejoras de comportamiento",
   "- **Velocidad adaptativa:** avanza rápido cuando la distancia es grande y frena progresivamente al acercarse: `vel = map(constrain(d, 25, 100), 25, 100, 120, 220)`.\n- **Aviso de batería baja:** mide el voltaje de la batería con un divisor en un pin analógico y pita si baja de 6,6 V (3,3 V por celda).\n- **Modo exploración** que gira ligeramente al azar cada cierto tiempo para no recorrer siempre el mismo camino.",
   "### Documentar",
   "Termina con un informe: qué funcionó, qué no, datos de las pruebas, y una lista de mejoras para la versión 2. ¡Felicidades: has construido tu primer robot autónomo completo!"],
  c: {l: "cpp", t: "// Velocidad adaptativa y aviso de batería baja\n// Divisor en A2: 10 kΩ desde la batería (+) a A2 y 10 kΩ de A2 a GND (la mitad del voltaje)\nint velocidadSegun(float d) {\n  return map(constrain((int)d, DIST_MIN, 100), DIST_MIN, 100, 120, 220);\n}\n\nfloat voltajeBateria() {\n  return analogRead(A2) * 5.0 / 1023.0 * 2.0;   // ×2 por el divisor\n}\n\nunsigned long tBateria = 0;\nvoid revisarBateria() {\n  if (millis() - tBateria < 5000) return;\n  tBateria = millis();\n  if (voltajeBateria() < 6.6) tone(ZUMBADOR, 2000, 200);   // 3,3 V por celda\n}"},
  sg: "No descargues las baterías de litio por debajo de unos 3 V por celda: el aviso de batería baja protege tu batería.",
  er: ["Cambiar varias cosas a la vez entre pruebas.", "Probar siempre en el mismo escenario fácil."],
  q: [["¿Por qué el ultrasonido no detecta bien la pata de una silla?", ["Porque es de madera", "Porque es estrecha y el cono del sonido no recibe un buen eco", "Porque es de noche", "Siempre la detecta"], 1, "Los objetos estrechos devuelven poco eco."],
   ["¿Qué hace la velocidad adaptativa?", ["Va siempre al máximo", "Frena al acercarse a un obstáculo", "Gira al azar", "Mide la batería"], 1, "Más distancia, más velocidad."],
   ["¿Por qué un divisor para medir la batería de 7,4 V con el Arduino?", ["Para cargarla", "Porque el pin analógico solo admite hasta 5 V", "Para aumentar el voltaje", "No hace falta"], 1, "El divisor reduce el voltaje a la mitad."],
   ["¿Qué voltaje por celda indica batería de litio baja?", ["4,2 V", "3,7 V", "Unos 3,3 V", "1,5 V"], 2, "Conviene parar antes de llegar a unos 3 V."],
   ["¿Qué solución ayuda contra objetos blandos que absorben el sonido?", ["Más velocidad", "Un parachoques o un sensor láser ToF", "Quitar el servo", "Más LED"], 1, "Otro tipo de sensor complementa al ultrasonido."]]}
 ]},

{id: "M18", n: 4, t: "Proyecto: robot seguidor de línea", d: "Construye un robot que sigue una línea negra sobre fondo blanco usando sensores infrarrojos, desde el control todo-nada hasta el PID, y prepáralo para competir.", dep: ["M14", "M16"],
 obj: ["Leer y calibrar una barra de sensores infrarrojos de línea.", "Calcular la posición de la línea.", "Programar un control todo-nada y luego un PID.", "Ajustar el robot para pistas de competición."],
 prac: ["Montaje y calibración de los sensores.", "Seguidor con PID en una pista propia."],
 mat: ["Chasis 2WD (mejor ligero y bajo) o el robot del M17", "Barra de 5 sensores IR (TCRT5000 o QTR)", "Arduino Nano o Uno", "Driver TB6612FNG", "Batería", "Cartulina blanca grande y cinta aislante negra de 19 mm"],
 pj: {t: "Entrega: seguidor de línea en pista", h: 1, d: "Tu robot debe completar una pista con curvas y una curva cerrada en el menor tiempo posible sin salirse.",
  pasos: ["Construye una pista cerrada de al menos 4 m con rectas, curvas suaves y una curva de 90°.", "Calibra los sensores en la pista.", "Mide el tiempo de 3 vueltas con el control todo-nada y con el PID.", "Anota los valores finales de Kp, Kd (y Ki) y la velocidad base.", "Graba un vídeo de la mejor vuelta.", "Entrega código, tabla de tiempos y explicación del ajuste."],
  crit: ["El robot completa 3 vueltas sin salirse.", "Usa control PID con posición ponderada.", "Incluye calibración automática al inicio.", "Hay una tabla comparando todo-nada y PID.", "El código está documentado."],
  rub: [["Completar la pista sin salirse", 30], ["Tiempo por vuelta", 20], ["Calidad del control (suavidad, PID bien ajustado)", 25], ["Documentación y análisis", 25]]},
 L: [
 {t: "El principio: sensores infrarrojos de línea", h: 1, s: 1, p: "¿Cómo «ve» un robot una línea negra en el suelo?",
  o: ["Explicar cómo distinguen los sensores IR una superficie blanca de una negra.", "Elegir y colocar la barra de sensores."],
  x: ["Un sensor de reflexión como el **TCRT5000** tiene un **LED infrarrojo** que ilumina el suelo y un **fototransistor** que mide cuánta luz vuelve:",
   "- **Superficie blanca:** refleja mucha luz infrarroja → el fototransistor conduce mucho.\n- **Superficie negra:** absorbe la luz → vuelve poca.",
   "Según el circuito, la salida analógica sube o baja con el reflejo; en muchos módulos, **negro = valor alto** (poca reflexión). Muchos módulos tienen también una salida **digital** con un potenciómetro para el umbral, pero para un buen seguidor conviene la lectura **analógica**.",
   "### Barras de sensores",
   "Con un solo sensor el robot solo sabe «estoy en la línea o no». Con una **barra de 5 u 8 sensores** en fila, sabe **dónde** está la línea respecto al centro del robot y **cuánto** se ha desviado, lo que permite un control mucho más fino. Las barras **QTR** de Pololu y las placas de 5 TCRT5000 son muy populares.",
   "### Colocación",
   "- **Altura:** a **3–8 mm** del suelo (según el modelo). Muy lejos, todo parece gris; muy cerca, los sensores rozan.\n- **Delante de las ruedas:** cuanto más adelantada, antes ve las curvas (pero más brusca será la corrección). Unos 5–8 cm por delante del eje es un buen comienzo.\n- **Separación** entre sensores parecida al ancho de la línea (las cintas aislantes miden 19 mm; muchas pistas usan 15–20 mm).\n- **Protección de la luz ambiente:** el sol y algunas lámparas emiten infrarrojo; una pequeña pantalla alrededor de los sensores ayuda.",
   "### La pista",
   "Cartulina o lona **blanca mate** con **cinta aislante negra**. Evita superficies brillantes (reflejan como el blanco aunque sean oscuras) y curvas de radio menor que el ancho del robot."],
  k: "Blanco refleja el IR, negro lo absorbe. Una barra de 5–8 sensores a 3–8 mm del suelo dice dónde está la línea, no solo si está.",
  er: ["Colocar los sensores demasiado altos.", "Pista brillante que confunde a los sensores."],
  q: [["¿Qué superficie refleja más luz infrarroja?", ["Negra", "Blanca"], 1, "El negro absorbe la luz."],
   ["¿Qué ventaja tiene una barra de 5 sensores frente a uno solo?", ["Consume menos", "Sabe dónde está la línea y cuánto se ha desviado", "Es más barata", "No necesita calibración"], 1, "Permite un control proporcional."],
   ["¿A qué altura aproximada se colocan los sensores TCRT5000?", ["3–8 mm", "5 cm", "20 cm", "Tocando el suelo"], 0, "A pocos milímetros del suelo."],
   ["¿Qué tiene un TCRT5000?", ["Un LED IR y un fototransistor", "Un micrófono", "Un imán", "Un motor"], 0, "Emite y recibe luz infrarroja."],
   ["¿Por qué evitar una pista brillante?", ["Porque es cara", "Porque los reflejos confunden a los sensores", "Porque se mancha", "No importa"], 1, "Un negro brillante puede reflejar como el blanco."]]},
 {t: "Montaje y calibración de los sensores", h: 2, s: 1, p: "¿Por qué el mismo robot funciona en tu casa y falla en la competición?",
  o: ["Montar y cablear la barra de sensores.", "Programar una calibración automática de mínimos y máximos."],
  x: ["### Montaje",
   "Fija la barra con separadores o un soporte rígido a la altura correcta, centrada respecto al eje del robot y perpendicular a la dirección de avance. Conecta las salidas analógicas de los 5 sensores a **A0–A4** (en el Nano tienes A0–A7), VCC a 5 V y GND. Si la barra tiene un pin para encender los LED (*LEDON* o *IR*), conéctalo a 5 V o a un pin digital.",
   "### Por qué calibrar",
   "Cada sensor es ligeramente distinto, y los valores cambian con la **altura**, la **luz ambiente** y el **material** de la pista. Un umbral fijo que funciona en tu mesa puede fallar en otra pista. La solución es **calibrar** al inicio en la pista real.",
   "### Calibración automática",
   "- Al arrancar, el robot **gira despacio sobre sí mismo** a un lado y al otro durante unos 3 segundos, de forma que todos los sensores pasen por encima del blanco y del negro.\n- Durante ese tiempo, para cada sensor se guarda el valor **mínimo** y el **máximo** leídos.\n- Después, cada lectura se **normaliza** a una escala de 0 (blanco) a 1000 (negro): `v = map(lectura, min, max, 0, 1000)` limitado con `constrain`.",
   "Así todos los sensores hablan «el mismo idioma», sea cual sea la pista. Guarda los valores en la EEPROM si quieres que el robot recuerde la última calibración.",
   "### Comprobar",
   "Envía las 5 lecturas normalizadas por el trazador serie y desliza el robot a mano sobre la línea: debes ver cómo el «pico» se desplaza de un sensor al siguiente."],
  c: {l: "cpp", t: "// Calibración automática de 5 sensores en A0–A4\nconst int N = 5;\nconst int PINES[N] = {A0, A1, A2, A3, A4};\nint minimo[N], maximo[N], valor[N];   // valor normalizado: 0 (blanco) a 1000 (negro)\n\nvoid calibrar() {\n  for (int i = 0; i < N; i++) { minimo[i] = 1023; maximo[i] = 0; }\n  unsigned long inicio = millis();\n  while (millis() - inicio < 3000) {\n    int fase = ((millis() - inicio) / 750) % 2;      // alterna el sentido de giro\n    mover(fase ? 110 : -110, fase ? -110 : 110);\n    for (int i = 0; i < N; i++) {\n      int v = analogRead(PINES[i]);\n      minimo[i] = min(minimo[i], v);\n      maximo[i] = max(maximo[i], v);\n    }\n  }\n  mover(0, 0);\n}\n\nvoid leerSensores() {\n  for (int i = 0; i < N; i++) {\n    int v = analogRead(PINES[i]);\n    valor[i] = constrain(map(v, minimo[i], maximo[i], 0, 1000), 0, 1000);\n  }\n}"},
  pr: {m: ["robot con la barra de sensores", "pista de cartulina y cinta"], p: ["Monta la barra a unos 5 mm del suelo.", "Imprime las lecturas crudas sobre blanco y sobre negro.", "Implementa la calibración automática y comprueba que la línea da ~1000 y el blanco ~0 en todos los sensores.", "Repite la calibración con otra luz o en otra superficie y compara."], e: "Lecturas normalizadas coherentes en los cinco sensores.", sim: "Wokwi no simula la pista, pero puedes simular los sensores con potenciómetros."},
  er: ["No calibrar en la pista donde se va a competir.", "Confundir qué extremo es blanco y cuál negro en la normalización."],
  q: [["¿Por qué calibrar los sensores en la pista real?", ["Porque cambian con la altura, la luz y el material", "Para gastar batería", "Porque el código lo exige siempre", "No hace falta"], 0, "Los valores dependen del entorno."],
   ["¿Qué se guarda durante la calibración?", ["El mínimo y el máximo de cada sensor", "Solo la media", "La temperatura", "Nada"], 0, "Para normalizar después."],
   ["¿Qué hace el robot mientras se calibra?", ["Avanza rápido", "Gira despacio para pasar sobre blanco y negro", "Se queda quieto", "Pita"], 1, "Así todos los sensores ven ambos colores."],
   ["Tras normalizar, ¿qué valor corresponde al negro en el ejemplo?", ["0", "500", "1000", "1023"], 2, "Escala de 0 (blanco) a 1000 (negro)."],
   ["¿Dónde se pueden guardar los valores de calibración para que no se pierdan?", ["En la RAM", "En la EEPROM", "En el cable", "En el servo"], 1, "La EEPROM conserva datos sin alimentación."]]},
 {t: "Control todo-nada", h: 1.5, s: 1, p: "¿Cuál es la forma más sencilla de seguir una línea?",
  o: ["Programar un seguidor de línea con reglas simples.", "Reconocer las limitaciones del control todo-nada."],
  x: ["La primera versión usa **reglas** según qué sensores ven la línea:",
   "- **El sensor central** ve negro → avanzar recto.\n- **Un sensor izquierdo** ve negro → la línea está a la izquierda → girar a la izquierda (rueda izquierda más lenta).\n- **Un sensor derecho** ve negro → girar a la derecha.\n- **Los sensores extremos** ven negro → la línea está muy desviada → giro fuerte (una rueda incluso hacia atrás).\n- **Ningún sensor** ve negro → el robot ha perdido la línea → seguir girando hacia el lado donde la vio por última vez.",
   "Un sensor «ve negro» si su valor normalizado supera un umbral (por ejemplo, 500).",
   "### Recordar el último lado",
   "Es clave: en una curva cerrada, la línea sale por un lado del campo de visión. Guardando en una variable el último lado en que se vio, el robot sabe hacia dónde girar para recuperarla, en lugar de seguir recto y salirse.",
   "### Limitaciones",
   "Este control es **todo-nada** por zonas: las correcciones son bruscas, el robot **zigzaguea** sobre la línea, y para no salirse hay que ir **despacio**. Aun así, es un buen primer paso y suele bastar para pistas sencillas. En la siguiente lección lo sustituiremos por un **PID**, que corrige de forma proporcional a cuánto se ha desviado."],
  c: {l: "cpp", t: "// Seguidor de línea todo-nada con 5 sensores normalizados (valor[0] = izquierda)\nconst int UMBRAL = 500, VEL = 140;\nint ultimoLado = 0;   // -1 izquierda, 1 derecha\n\nvoid seguirTodoNada() {\n  leerSensores();\n  bool s[5];\n  for (int i = 0; i < 5; i++) s[i] = valor[i] > UMBRAL;   // true = ve la línea\n\n  if (s[2])            { mover(VEL, VEL); }                     // centro\n  else if (s[1])       { mover(VEL / 2, VEL);  ultimoLado = -1; }\n  else if (s[3])       { mover(VEL, VEL / 2);  ultimoLado = 1; }\n  else if (s[0])       { mover(-VEL / 2, VEL); ultimoLado = -1; } // muy a la izquierda\n  else if (s[4])       { mover(VEL, -VEL / 2); ultimoLado = 1; }\n  else {                                                         // línea perdida\n    if (ultimoLado < 0) mover(-VEL / 2, VEL);\n    else                mover(VEL, -VEL / 2);\n  }\n}"},
  pr: {m: ["robot seguidor calibrado", "pista"], p: ["Carga el control todo-nada.", "Prueba en una recta y en una curva suave.", "Prueba en la curva de 90° con y sin la memoria del último lado.", "Mide el tiempo de una vuelta a distintas velocidades y encuentra la máxima sin salirse."], e: "El robot sigue la línea zigzagueando; con la memoria del último lado recupera la línea en las curvas cerradas.", sim: "Existen simuladores de seguidores de línea en el navegador para probar algoritmos."},
  er: ["No guardar el último lado y perder la línea en curvas cerradas.", "Ir demasiado rápido con un control tan brusco."],
  q: [["Si solo el sensor de la derecha ve la línea, el robot debe…", ["Girar a la izquierda", "Girar a la derecha", "Parar", "Ir recto"], 1, "La línea está a su derecha."],
   ["¿Para qué sirve recordar el último lado en que se vio la línea?", ["Para pitar", "Para recuperarla cuando sale del campo de visión", "Para medir la batería", "No sirve"], 1, "Así sabe hacia dónde girar."],
   ["¿Cuál es el principal defecto del control todo-nada?", ["No sigue la línea", "Zigzaguea y obliga a ir despacio", "Necesita WiFi", "No usa sensores"], 1, "Las correcciones son bruscas."],
   ["Con UMBRAL = 500, un sensor con valor 820 se considera…", ["Blanco", "Línea (negro)"], 1, "Supera el umbral."],
   ["Si ningún sensor ve la línea y el último lado fue la izquierda, el robot…", ["Gira a la izquierda", "Gira a la derecha", "Se para siempre", "Acelera recto"], 0, "Busca la línea por donde la perdió."]]},
 {t: "Control PID aplicado al seguidor", h: 2, s: 1, p: "¿Cómo siguen la línea a toda velocidad los robots de competición sin zigzaguear?",
  o: ["Calcular la posición de la línea con una media ponderada.", "Programar y ajustar un PID para el seguidor de línea."],
  x: ["### La posición de la línea",
   "Con los valores normalizados (0–1000), se calcula una **media ponderada**: cada sensor tiene un peso según su posición (0, 1000, 2000, 3000, 4000 de izquierda a derecha):",
   "- **posición = Σ(valor_i × i × 1000) / Σ(valor_i)**",
   "Si la línea está bajo el sensor central, la posición es **2000**; si está entre el central y el derecho, unos 2500. Así obtenemos una posición **continua**, mucho más precisa que «qué sensor la ve».",
   "### El PID (M16)",
   "- **Error = posición − 2000** (de −2000 a +2000; 0 = centrado).\n- **Corrección = Kp·error + Ki·∑error + Kd·(error − errorAnterior)**.\n- **Motor izquierdo = velocidadBase + corrección**; **motor derecho = velocidadBase − corrección** (limitados a −255…255).",
   "En la práctica, muchos seguidores usan solo **PD** (Ki = 0): el término D es el más importante para ir rápido sin oscilar.",
   "### Ajuste",
   "- **1.** Velocidad base baja (100), Ki = Kd = 0. Sube **Kp** desde 0,02 hasta que siga la línea; si oscila mucho, bájalo.\n- **2.** Sube **Kd** (por ejemplo, de 0,1 a 1) hasta que desaparezcan las oscilaciones.\n- **3.** Aumenta la **velocidad base** y reajusta Kp y Kd.\n- **4.** Un Ki muy pequeño solo si el robot tiende a quedar desplazado en las curvas largas.",
   "### Línea perdida",
   "Si la suma de todos los valores es muy baja (ningún sensor ve la línea), conserva la **última posición** (0 o 4000), y el PID girará con fuerza hacia ese lado.",
   "El PID debe ejecutarse **a un ritmo constante** y rápido (cada 5–10 ms): elimina cualquier `delay()` y no imprimas por serie en cada vuelta durante la carrera."],
  c: {l: "cpp", t: "// Seguidor de línea con PD sobre la posición ponderada\nfloat Kp = 0.06, Kd = 0.5;\nint velBase = 150;\nlong ultimaPos = 2000;\nint errorAnterior = 0;\n\nlong posicionLinea() {\n  leerSensores();\n  long suma = 0, ponderada = 0;\n  for (int i = 0; i < 5; i++) { suma += valor[i]; ponderada += (long)valor[i] * i * 1000; }\n  if (suma < 300) return ultimaPos < 2000 ? 0 : 4000;   // línea perdida: extremo del último lado\n  ultimaPos = ponderada / suma;\n  return ultimaPos;\n}\n\nunsigned long tPID = 0;\nvoid seguirPID() {\n  if (millis() - tPID < 5) return;          // ritmo constante: cada 5 ms\n  tPID = millis();\n  int error = posicionLinea() - 2000;\n  float correccion = Kp * error + Kd * (error - errorAnterior);\n  errorAnterior = error;\n  int izq = constrain(velBase + correccion, -255, 255);\n  int der = constrain(velBase - correccion, -255, 255);\n  mover(izq, der);\n}"},
  pr: {m: ["robot seguidor calibrado", "pista", "computadora para ajustar"], p: ["Calcula y muestra por serie la posición de la línea moviendo el robot a mano.", "Implementa el control PD con velocidad base 100.", "Ajusta Kp, luego Kd; anota cada combinación y su resultado.", "Sube la velocidad base de 20 en 20 y reajusta.", "Compara el tiempo por vuelta con el del control todo-nada."], e: "El robot sigue la línea suavemente y más rápido que con el todo-nada.", sim: "Prueba el cálculo de la posición con potenciómetros en lugar de sensores."},
  er: ["Usar Kp demasiado grande: el robot oscila violentamente.", "Imprimir por serie en cada ciclo del PID: lo ralentiza."],
  q: [["Con 5 sensores y pesos 0–4000, ¿qué posición indica la línea centrada?", {n: 2000, tol: 0, u: ""}, null, "El sensor central tiene peso 2000."],
   ["Si la posición es 2600, ¿cuánto vale el error?", {n: 600, tol: 0, u: ""}, null, "2600 − 2000 = 600."],
   ["¿Qué término es clave para ir rápido sin oscilar en un seguidor?", ["Integral", "Derivativo", "Ninguno", "La batería"], 1, "El D amortigua las oscilaciones."],
   ["Con corrección positiva, el motor izquierdo…", ["Va más rápido", "Va más lento"], 0, "izq = base + corrección."],
   ["¿Cada cuánto conviene ejecutar el PID del seguidor?", ["Cada segundo", "Cada 5–10 ms", "Cada minuto", "Solo al arrancar"], 1, "Un ritmo rápido y constante."]]},
 {t: "Pistas y competencias", h: 1, p: "¿Qué tipos de pruebas de seguidores de línea existen en las competencias de robótica?",
  o: ["Conocer las categorías y reglas habituales de las competencias de seguidores.", "Construir pistas de práctica con distintos desafíos."],
  x: ["Los seguidores de línea son una de las categorías más populares en torneos escolares y universitarios de toda Latinoamérica y España. Aunque cada torneo tiene su **reglamento** (léelo siempre con atención), hay elementos comunes:",
   "### Categorías habituales",
   "- **Velocidad:** completar la pista en el menor tiempo. Gana el más rápido sin salirse.\n- **Velocista o *line follower* avanzado:** pistas largas con muchas curvas; robots muy ligeros con motores N20 de alta velocidad, a veces con turbina de succión para pegarse al suelo.\n- **Laberinto de líneas:** el robot debe encontrar la salida en una red de líneas con cruces y callejones, aprenderla y recorrerla después por el camino más corto.\n- **Rescate o desafíos** (por ejemplo, RoboCup Junior Rescue Line): línea con huecos, obstáculos, marcas de color en las intersecciones que indican el giro, rampas y una zona final de tarea.",
   "### Reglas típicas",
   "- **Dimensiones y peso máximos** del robot (por ejemplo, 20 × 20 cm y 1 kg).\n- **Autonomía total:** nada de control remoto durante la prueba.\n- **Línea** negra de 15–20 mm sobre fondo blanco (o al revés).\n- **Radio mínimo** de las curvas.\n- **Tiempo de calibración** antes de la salida y número de intentos.",
   "### Pistas de práctica",
   "Construye varias: una oval sencilla, una con curvas en S, otra con una curva de 90° y un cruce, y otra con un hueco de 10 cm en la línea. Usa cinta aislante sobre cartulina o lona blanca; une varias cartulinas por detrás con cinta. Los cruces exigen ignorar la lectura cuando **todos** los sensores ven negro (seguir recto).",
   "### Espíritu de la competencia",
   "Comparte, aprende de otros equipos, documenta tu robot y respeta a los jueces. Muchas competencias valoran también la **documentación** y la **presentación** del proyecto."],
  er: ["No leer el reglamento y llevar un robot que excede las medidas.", "Practicar solo en una pista fácil."],
  q: [["¿Qué tienen que hacer los robots en la categoría de laberinto de líneas?", ["Ir lo más rápido posible en un óvalo", "Encontrar y aprender el camino más corto hacia la salida", "Pelear con otros robots", "Volar"], 1, "Exploran, aprenden y repiten el camino óptimo."],
   ["¿Qué ancho de línea es habitual en competiciones?", ["1–2 mm", "15–20 mm", "10 cm", "1 m"], 1, "Similar a la cinta aislante."],
   ["¿Qué hace el robot en un cruce donde todos los sensores ven negro (si la regla es seguir recto)?", ["Girar siempre", "Seguir recto", "Retroceder", "Parar para siempre"], 1, "Es un cruce, no una curva."],
   ["¿Qué se debe leer antes de cualquier competencia?", ["Una novela", "El reglamento", "El manual del cautín", "Nada"], 1, "Cada torneo tiene sus propias reglas."],
   ["¿Está permitido el control remoto en las pruebas de seguidores?", ["Sí, siempre", "No; los robots deben ser autónomos", "Solo en las curvas", "Solo con WiFi"], 1, "Deben funcionar solos."]]},
 {t: "Mejoras: velocidad, cruces y curvas cerradas", h: 1.5, p: "¿Qué separa a un seguidor que termina la pista de uno que gana?",
  o: ["Aplicar mejoras mecánicas y de software para ganar velocidad.", "Gestionar cruces, curvas cerradas y huecos en la línea."],
  x: ["### Mecánica",
   "- **Ligereza:** cada gramo cuenta. Chasis de PCB o placa fina, batería LiPo pequeña (con todas las precauciones), Arduino Nano.\n- **Centro de gravedad bajo** y la barra de sensores adelantada.\n- **Motores** N20 de alta velocidad (por ejemplo, 1000 RPM con reducción 1:10 o 1:30) y **ruedas** con buen agarre (silicona o goma blanda), limpias de polvo.\n- **Rueda loca** sustituida por un apoyo deslizante bajo y liso.",
   "### Velocidad variable",
   "Ir siempre a la misma velocidad es poco eficiente: en las **rectas** se puede ir más rápido y en las **curvas** conviene frenar. Una regla sencilla: reducir la velocidad base en proporción al valor absoluto del error: `vel = velMax - k * abs(error)`. Las versiones más avanzadas **memorizan la pista** en la primera vuelta (con encoders) y aceleran en las rectas conocidas en las siguientes.",
   "### Curvas cerradas",
   "En curvas de 90°, la línea desaparece de golpe por un lado. Con la memoria del **último lado** y una posición extrema (0 o 4000), el PID gira con fuerza; si no basta, añade un caso especial: si se pierde la línea, girar en el sitio hacia ese lado hasta reencontrarla.",
   "### Cruces y huecos",
   "- **Cruce:** todos los sensores (o casi) ven negro → mantener la última corrección o ir recto unos milisegundos.\n- **Hueco:** ningún sensor ve la línea durante un tramo recto → seguir recto un tiempo limitado (por ejemplo, 300 ms) antes de considerar la línea perdida. Distinguir hueco de curva es la parte difícil: un hueco aparece cuando el error era casi 0; una curva perdida, cuando el error era grande.",
   "### Ajuste fino",
   "Registra el error a lo largo de la vuelta (en la EEPROM o por Bluetooth) y analízalo: verás dónde oscila el robot y dónde se sale. Prueba con la **batería cargada y a media carga**: el ajuste cambia con el voltaje."],
  c: {l: "cpp", t: "// Velocidad base variable según el error y tratamiento de huecos\nconst int VEL_MAX = 220, VEL_MIN = 120;\nunsigned long tSinLinea = 0;\n\nint velocidadSegunError(int error) {\n  return constrain(VEL_MAX - abs(error) / 20, VEL_MIN, VEL_MAX);\n}\n\nbool lineaVisible() {\n  long suma = 0;\n  for (int i = 0; i < 5; i++) suma += valor[i];\n  return suma > 300;\n}\n\n// En el bucle del seguidor:\n// if (!lineaVisible()) {\n//   if (tSinLinea == 0) tSinLinea = millis();\n//   if (abs(errorAnterior) < 400 && millis() - tSinLinea < 300) { mover(VEL_MIN, VEL_MIN); return; } // hueco: recto\n// } else tSinLinea = 0;"},
  sg: "Si usas baterías LiPo para aligerar el robot, cárgalas con cargador balanceador y bajo supervisión, y guárdalas en una bolsa ignífuga.",
  er: ["Subir la velocidad sin reajustar Kp y Kd.", "Confundir un hueco con una curva perdida."],
  q: [["¿Por qué conviene reducir la velocidad cuando el error es grande?", ["Para ahorrar batería", "Porque probablemente está en una curva", "Porque el sensor falla", "No conviene"], 1, "Las curvas requieren ir más despacio."],
   ["¿Qué distingue un hueco de una curva perdida?", ["El color", "El error justo antes: casi 0 en un hueco, grande en una curva", "La batería", "Nada"], 1, "En recta el error era pequeño."],
   ["¿Qué mejora mecánica ayuda a un seguidor rápido?", ["Hacerlo más pesado", "Hacerlo ligero y con ruedas de buen agarre", "Subir los sensores a 10 cm", "Usar ruedas lisas"], 1, "Menos peso y más agarre."],
   ["¿Qué permite memorizar la pista en la primera vuelta?", ["Los encoders", "El zumbador", "El LED", "El reglamento"], 0, "Miden la distancia recorrida en cada tramo."],
   ["¿Por qué probar con la batería a distintas cargas?", ["Por diversión", "Porque el ajuste del PID cambia con el voltaje", "Para descargarla", "No hace falta"], 1, "La misma orden da distinta velocidad."]]}
 ]},

{id: "M19", n: 4, t: "Proyecto: carro a control remoto", d: "Construye un carro que se controla desde el móvil por Bluetooth o WiFi, o con un mando propio por radio, con telemetría y parada de seguridad.", dep: ["M11", "M14"],
 obj: ["Elegir la tecnología de comunicación adecuada para un vehículo teleoperado.", "Controlar el carro por Bluetooth, WiFi y radio.", "Enviar telemetría de vuelta al mando.", "Implementar una parada de seguridad ante la pérdida de señal."],
 prac: ["Control por Bluetooth con una app.", "Control por WiFi con una página web propia.", "Mando con joystick por radio nRF24L01."],
 mat: ["Chasis 2WD o 4WD", "Driver TB6612FNG (o dos para 4WD)", "ESP32 (o Arduino con HC-05)", "Batería 2S con interruptor y fusible", "Opcional: segundo Arduino con joystick y 2 módulos nRF24L01", "HC-SR04 para telemetría"],
 pj: {t: "Entrega: carro teleoperado", h: 1, d: "Demuestra tu carro superando un circuito de conos controlado a distancia, con telemetría visible y parada automática al perder la señal.",
  pasos: ["Prepara un circuito con 6 conos (o botellas) en zigzag y una zona de aparcamiento.", "Recorre el circuito 3 veces y cronometra.", "Muestra en el mando o en la página la batería y la distancia frontal.", "Demuestra la parada de seguridad apagando el mando o alejándote.", "Entrega el código del carro y del mando, y un manual de uso de una página."],
  crit: ["El carro se controla con suavidad en las cuatro direcciones.", "Hay telemetría de batería y distancia.", "Se detiene solo en menos de 1 s al perder la señal.", "Incluye freno automático ante un obstáculo cercano.", "Hay un manual de uso."],
  rub: [["Control y maniobrabilidad", 30], ["Telemetría", 20], ["Seguridad (parada por pérdida de señal y antichoque)", 30], ["Documentación y manual", 20]]},
 L: [
 {t: "Diseño y elección de la conexión", h: 1, s: 1, p: "Bluetooth, WiFi o radio: ¿cuál es mejor para un carro a control remoto?",
  o: ["Comparar las tecnologías de control remoto.", "Diseñar la arquitectura del carro y el protocolo de órdenes."],
  x: ["Un vehículo **teleoperado** lo conduce una persona a distancia. Aunque no decide solo, este proyecto reúne comunicación, motores, energía y seguridad. Lo primero es elegir la conexión:",
   "- **Bluetooth (HC-05 o BLE del ESP32):** alcance de unos 10 m, control desde una app del móvil, muy fácil de programar como un puerto serie. Ideal para empezar.\n- **WiFi (ESP32):** alcance de unos 20–50 m, control desde una **página web propia** en cualquier móvil o computadora, sin instalar apps; permite enviar mucha telemetría e incluso vídeo (con ESP32-CAM). Algo más de latencia.\n- **Radio nRF24L01:** alcance de decenas a cientos de metros, latencia muy baja, mando **físico con joystick** (más agradable de conducir). Requiere construir el mando.\n- **Infrarrojo:** muy limitado (necesita visión directa).",
   "En este módulo verás las tres principales; elige la que prefieras para el proyecto.",
   "### Arquitectura",
   "- **Carro:** controlador (ESP32 o Arduino), driver, motores, batería, sensor frontal y LED.\n- **Mando:** móvil, navegador o un Arduino con joystick.\n- **Enlace:** órdenes del mando al carro y **telemetría** del carro al mando.",
   "### Protocolo de órdenes",
   "Define mensajes sencillos y claros. Dos estilos:",
   "- **Por botones (discreto):** una letra por acción: `F` adelante, `B` atrás, `L` izquierda, `R` derecha, `S` parar, y `0–9` para la velocidad. Lo usan muchas apps de Bluetooth.\n- **Por joystick (continuo):** dos números, **avance** y **giro**, de −100 a 100. Se convierten en velocidad de cada rueda con la **mezcla diferencial**: `izq = avance + giro`, `der = avance − giro` (limitados). Mucho más suave de conducir.",
   "Y una regla de seguridad desde el diseño: el carro **se detiene si no recibe órdenes** durante un tiempo (lección 6)."],
  k: "Bluetooth: fácil y cercano. WiFi: página web y telemetría. Radio: mando físico y largo alcance. Mezcla diferencial: izq = avance + giro; der = avance − giro.",
  er: ["Elegir WiFi para un carro de carreras que necesita respuesta inmediata sin tener en cuenta la latencia.", "No definir el protocolo antes de programar el carro y el mando."],
  q: [["¿Qué tecnología permite controlar el carro desde el navegador sin instalar apps?", ["Infrarrojo", "WiFi con el ESP32", "nRF24L01", "I2C"], 1, "El ESP32 sirve una página web."],
   ["¿Qué tecnología da más alcance con un mando físico?", ["Bluetooth", "nRF24L01", "Infrarrojo", "USB"], 1, "Decenas o cientos de metros."],
   ["Con avance = 50 y giro = 20, ¿velocidad de la rueda izquierda?", {n: 70, tol: 0, u: ""}, null, "izq = avance + giro = 70."],
   ["Con avance = 50 y giro = 20, ¿velocidad de la rueda derecha?", {n: 30, tol: 0, u: ""}, null, "der = avance − giro = 30."],
   ["¿Qué debe hacer el carro si deja de recibir órdenes?", ["Seguir a toda velocidad", "Detenerse", "Girar sin parar", "Pitar sin parar"], 1, "Es una regla básica de seguridad."]]},
 {t: "Control por Bluetooth con el móvil", h: 2, s: 1, p: "¿Cómo conviertes tu móvil en el mando de tu carro?",
  o: ["Recibir órdenes de una app de Bluetooth y mover el carro.", "Implementar velocidad ajustable y respuesta al móvil."],
  x: ["Usaremos el modelo de órdenes **por botones**: la mayoría de las apps de «Bluetooth RC car» para Android envían una letra al pulsar cada botón (y otra al soltar). Consulta en la app qué letras envía y ajusta el código.",
   "### Con Arduino + HC-05",
   "Conecta el HC-05 como en el M11 (con SoftwareSerial en los pines 10 y 11 y divisor en el RX del módulo). El carro lee cada carácter y actualiza la acción y la velocidad.",
   "### Con ESP32 y Bluetooth clásico",
   "El ESP32 original admite Bluetooth clásico con la biblioteca **BluetoothSerial**: `SerialBT.begin(\"MiCarro\")` y luego `SerialBT.available()` y `SerialBT.read()`, igual que un puerto serie. Las variantes S3 y C3 solo tienen **BLE**: para ellas, usa una biblioteca BLE de tipo «UART» y una app BLE.",
   "### Detalles para una buena conducción",
   "- Usa una **rampa de aceleración** (M14) para que los cambios no sean bruscos.\n- Al **girar**, reduce la velocidad de una rueda en lugar de invertirla, para un giro más natural; usa el giro en el sitio solo a baja velocidad.\n- Guarda el momento de la **última orden** recibida: lo necesitarás para la parada de seguridad.\n- Responde al móvil con un «OK» o con datos de telemetría (lección 5).",
   "### Emparejamiento",
   "Empareja el móvil con el módulo en los ajustes de Bluetooth (clave 1234 o 0000) y luego conéctalo desde la app. Si no aparece, comprueba la alimentación del módulo y que su LED parpadea rápido (esperando conexión)."],
  c: {l: "cpp", t: "// Carro por Bluetooth con ESP32 (Bluetooth clásico) y TB6612FNG\n#include \"BluetoothSerial.h\"\nBluetoothSerial SerialBT;\n\nint velocidad = 180;\nunsigned long ultimaOrden = 0;\n\nvoid aplicar(char c) {\n  ultimaOrden = millis();\n  if (c >= '0' && c <= '9') { velocidad = map(c - '0', 0, 9, 80, 255); return; }\n  switch (c) {\n    case 'F': mover(velocidad, velocidad); break;\n    case 'B': mover(-velocidad, -velocidad); break;\n    case 'L': mover(velocidad / 3, velocidad); break;     // giro suave\n    case 'R': mover(velocidad, velocidad / 3); break;\n    case 'S': mover(0, 0); break;\n  }\n}\n\nvoid setup() {\n  configurarMotores();            // pines y STBY, como en el M14\n  SerialBT.begin(\"MiCarro\");      // nombre visible en el móvil\n}\n\nvoid loop() {\n  while (SerialBT.available()) aplicar(SerialBT.read());\n  if (millis() - ultimaOrden > 700) mover(0, 0);   // parada de seguridad\n}"},
  pr: {m: ["carro con ESP32 (o Arduino + HC-05)", "móvil Android con una app de control por Bluetooth"], p: ["Revisa en la app qué letras envía cada botón.", "Carga el programa y empareja el móvil.", "Prueba las cuatro direcciones con las ruedas en el aire.", "Ajusta la velocidad con los números o el deslizador de la app.", "Conduce en el suelo y ajusta la suavidad de los giros."], e: "El carro responde a los botones del móvil y se detiene al soltar o al perder la conexión.", sim: "Prueba la lógica enviando letras desde el monitor serie."},
  sg: "Conduce en un espacio despejado, lejos de escaleras, personas distraídas y mascotas.",
  er: ["Usar letras distintas a las que envía la app.", "No detener el carro al perder la conexión."],
  q: [["¿Con qué biblioteca recibe el ESP32 datos por Bluetooth clásico?", ["WiFi.h", "BluetoothSerial", "Servo.h", "Wire.h"], 1, "Se usa como un puerto serie."],
   ["¿Qué variantes del ESP32 solo tienen BLE?", ["ESP32 original", "ESP32-S3 y C3", "Todas", "Ninguna"], 1, "No tienen Bluetooth clásico."],
   ["En el ejemplo, ¿qué hace la orden '5'?", ["Avanzar", "Cambiar la velocidad", "Girar", "Parar"], 1, "Los números ajustan la velocidad."],
   ["¿Por qué reducir una rueda en lugar de invertirla al girar?", ["Para un giro más suave y natural", "Para ahorrar Bluetooth", "Porque no se puede invertir", "Por estética"], 0, "El giro en el sitio es brusco a alta velocidad."],
   ["¿Qué guarda la variable ultimaOrden?", ["La velocidad", "El momento en que llegó la última orden", "La letra recibida", "El voltaje"], 1, "Sirve para la parada de seguridad."]]},
 {t: "Control por WiFi con una página web", h: 2, s: 1, p: "¿Puedes conducir tu carro desde cualquier navegador, incluso desde un iPhone?",
  o: ["Servir desde el ESP32 una página de control táctil.", "Enviar órdenes continuas desde el navegador con JavaScript."],
  x: ["El ESP32 crea su propia red WiFi (modo **punto de acceso**, M11) y sirve una **página web** con los controles. Cualquier dispositivo con navegador (Android, iPhone, tableta, computadora) puede conducir el carro, sin instalar nada.",
   "### La página",
   "Una página sencilla con cinco botones grandes (adelante, atrás, izquierda, derecha, parar) o un **joystick táctil** dibujado en un canvas. Con **JavaScript**, cada pulsación llama a una ruta del ESP32, por ejemplo `/mover?a=60&g=-20` (avance y giro de −100 a 100). Para que el carro se detenga al soltar, se envía `a=0&g=0` en el evento de soltar el dedo.",
   "### Órdenes continuas y latido",
   "Mientras el dedo está pulsado, la página **reenvía la orden cada 150–200 ms**. Ese reenvío actúa como **latido** (*heartbeat*): si el carro deja de recibirlo (el móvil se bloqueó o salió del alcance), se detiene (lección 6).",
   "### En el ESP32",
   "- Rutas: `/` devuelve la página; `/mover` lee los parámetros con `servidor.arg(\"a\")`, aplica la mezcla diferencial y responde con la telemetría en formato **JSON** (`{\"bat\":7.6,\"dist\":42}`).\n- `servidor.handleClient()` en cada vuelta de `loop()`.\n- La página se guarda en el código como una cadena (con `R\"(... )\"`) o en el sistema de archivos del ESP32.",
   "### Para ir más allá",
   "Los **WebSockets** (biblioteca WebSockets o ESPAsyncWebServer) mantienen una conexión abierta y reducen la latencia; son la opción profesional para el control en tiempo real. Con una **ESP32-CAM** puedes añadir vídeo en la misma página."],
  c: {l: "cpp", t: "// Ruta de control y página mínima (parte del programa del ESP32)\nconst char PAGINA[] = R\"(<!doctype html><meta name=viewport content='width=device-width,user-scalable=no'>\n<style>button{width:30vw;height:20vw;font-size:2em;margin:1vw}</style>\n<div style='text-align:center'>\n<button data-a=70 data-g=0>▲</button><br>\n<button data-a=0 data-g=-60>◀</button><button data-a=0 data-g=0>■</button><button data-a=0 data-g=60>▶</button><br>\n<button data-a=-70 data-g=0>▼</button><p id=t></p></div>\n<script>\nlet orden={a:0,g:0};\nfunction enviar(){fetch(`/mover?a=${orden.a}&g=${orden.g}`).then(r=>r.json()).then(d=>t.textContent=`Batería ${d.bat} V · Distancia ${d.dist} cm`).catch(()=>{})}\ndocument.querySelectorAll('button').forEach(b=>{\n b.onpointerdown=()=>{orden={a:b.dataset.a,g:b.dataset.g};enviar()};\n b.onpointerup=b.onpointerleave=()=>{orden={a:0,g:0};enviar()};});\nsetInterval(enviar,200);   // latido: reenvía la orden cada 200 ms\n</script>)\";\n\nvoid rutaMover() {\n  int a = servidor.arg(\"a\").toInt(), g = servidor.arg(\"g\").toInt();\n  ultimaOrden = millis();\n  int izq = constrain(a + g, -100, 100), der = constrain(a - g, -100, 100);\n  mover(izq * 255 / 100, der * 255 / 100);\n  servidor.send(200, \"application/json\",\n    \"{\\\"bat\\\":\" + String(voltajeBateria(), 1) + \",\\\"dist\\\":\" + String((int)distancia) + \"}\");\n}"},
  pr: {m: ["carro con ESP32", "móvil o tableta"], p: ["Integra la página y la ruta /mover en el programa del servidor web del M11.", "Conéctate a la red del carro y abre 192.168.4.1.", "Conduce y comprueba que se detiene al soltar el botón.", "Bloquea la pantalla del móvil mientras avanza y comprueba que el carro se para.", "Mide la latencia aproximada (tiempo entre pulsar y que el carro reaccione)."], e: "El carro se conduce desde el navegador y se detiene al soltar o al perder la conexión.", sim: "Wokwi simula el servidor web del ESP32 y permite abrir la página."},
  er: ["No enviar la orden de parar al soltar el botón.", "Olvidar el latido y que el carro siga si el móvil se bloquea."],
  q: [["¿Qué ventaja tiene controlar por una página web?", ["No necesita batería", "Funciona en cualquier navegador sin instalar apps", "Tiene más alcance que la radio", "No necesita WiFi"], 1, "Android, iPhone o computadora."],
   ["¿Qué hace setInterval(enviar, 200) en la página?", ["Detiene el carro", "Reenvía la orden cada 200 ms como latido", "Cambia la página", "Mide la batería"], 1, "Mantiene viva la conexión."],
   ["¿En qué formato responde el ESP32 con la telemetría en el ejemplo?", ["MP3", "JSON", "PDF", "Imagen"], 1, "Un texto con pares clave-valor."],
   ["¿Qué tecnología reduce la latencia frente a peticiones HTTP sueltas?", ["WebSockets", "Correo electrónico", "Infrarrojo", "SD"], 0, "Mantienen una conexión abierta."],
   ["¿Qué debe enviar la página al levantar el dedo?", ["La última orden otra vez", "Avance y giro a 0", "Nada", "Un error"], 1, "Para que el carro se detenga."]]},
 {t: "Mando propio con joystick y nRF24L01", h: 2, p: "¿Cómo construyes un mando como el de los coches de radiocontrol de verdad?",
  o: ["Construir un mando con Arduino, joystick y radio.", "Recibir los datos en el carro y convertirlos en movimiento."],
  x: ["Un mando físico con joystick es mucho más cómodo de conducir que una pantalla táctil, y la radio **nRF24L01** da más alcance y menos latencia que el Bluetooth o el WiFi.",
   "### El mando (emisor)",
   "- Arduino Nano + **joystick** analógico (ejes en A0 y A1, botón en D2) + **nRF24L01** (por SPI: CE y CSN en 9 y 10, más SCK, MOSI y MISO) alimentado a **3,3 V con un condensador de 10–100 µF**.\n- Lee el joystick con **zona muerta** (M13), lo convierte a −100…100 y envía una **estructura** con avance, giro, botones y un **contador** que aumenta en cada envío, unas **50 veces por segundo**.\n- Alimentación: una batería de 9 V o, mejor, un pequeño paquete de pilas o una celda con un regulador. Mete todo en una caja (impresa en 3D o una caja de plástico).",
   "### El carro (receptor)",
   "- Otro nRF24L01 con la **misma dirección y canal**, en modo escucha.\n- Cuando llega un paquete, aplica la mezcla diferencial y guarda el momento de recepción (para la parada de seguridad).\n- Puede **responder con telemetría** usando los paquetes de acuse de recibo (*ACK payload*) de la biblioteca RF24, sin cambiar de modo.",
   "### Consejos",
   "- Usa la **misma estructura** (mismo orden y tipos) en el emisor y el receptor. Cuidado: un `int` ocupa 2 bytes en el Arduino Uno y 4 en el ESP32; usa tipos de tamaño fijo como `int16_t` si mezclas placas.\n- Elige un **canal** poco usado (por ejemplo, 100) para alejarte del WiFi.\n- Si la comunicación falla de forma intermitente, casi siempre es la **alimentación** del nRF24L01: revisa el condensador y los 3,3 V.",
   "También puedes usar **ESP-NOW** si el carro y el mando son ESP32: comunicación directa entre placas sin router, con un código muy sencillo."],
  c: {l: "cpp", t: "// Receptor nRF24L01 en el carro (la estructura debe coincidir con la del mando)\n#include <SPI.h>\n#include <RF24.h>\n\nRF24 radio(9, 10);                       // CE, CSN\nconst byte DIRECCION[6] = \"CARRO\";\nstruct Paquete { int16_t avance; int16_t giro; uint8_t botones; uint16_t contador; };\nPaquete p;\nunsigned long ultimoPaquete = 0;\n\nvoid setup() {\n  configurarMotores();\n  radio.begin();\n  radio.setChannel(100);\n  radio.setPALevel(RF24_PA_LOW);\n  radio.openReadingPipe(1, DIRECCION);\n  radio.startListening();\n}\n\nvoid loop() {\n  if (radio.available()) {\n    radio.read(&p, sizeof(p));\n    ultimoPaquete = millis();\n    int izq = constrain(p.avance + p.giro, -100, 100);\n    int der = constrain(p.avance - p.giro, -100, 100);\n    mover(izq * 255 / 100, der * 255 / 100);\n  }\n  if (millis() - ultimoPaquete > 500) mover(0, 0);   // parada de seguridad\n}"},
  er: ["Estructuras distintas en el emisor y el receptor.", "Alimentar el nRF24L01 a 5 V o sin condensador."],
  q: [["¿Cuántas veces por segundo envía el mando en el ejemplo, aproximadamente?", {n: 50, tol: 0.1, u: "veces"}, null, "Unas 50, con un envío cada 20 ms."],
   ["¿Qué debe coincidir entre emisor y receptor?", ["El color", "La dirección, el canal y la estructura de datos", "La batería", "El tipo de motor"], 1, "Si no, no se entienden."],
   ["¿Por qué usar int16_t en lugar de int al mezclar Arduino y ESP32?", ["Porque int ocupa distinto tamaño en cada placa", "Porque es más rápido siempre", "Porque int no existe", "No hay diferencia"], 0, "int16_t ocupa siempre 2 bytes."],
   ["La comunicación falla de forma intermitente. ¿Qué revisas primero?", ["El color del cable", "La alimentación y el condensador del nRF24L01", "La pintura", "El zumbador"], 1, "Es la causa más frecuente."],
   ["¿Qué alternativa permite comunicar dos ESP32 sin router?", ["ESP-NOW", "HDMI", "I2C largo", "MQTT sin broker"], 0, "Comunicación directa entre placas."]]},
 {t: "Telemetría: batería y distancia", h: 1.5, p: "¿Cómo sabe quien conduce que la batería del carro se está agotando?",
  o: ["Medir y enviar datos del carro al mando.", "Mostrar la telemetría de forma útil y con alertas."],
  x: ["La **telemetría** son los datos que el vehículo envía de vuelta: estado de la batería, distancia al obstáculo, velocidad, temperatura del driver, intensidad de la señal. Permite conducir con información y anticipar problemas.",
   "### Qué medir",
   "- **Voltaje de la batería:** con un divisor de voltaje hacia un pin analógico (M17). En un ESP32, con un divisor que lleve el máximo (8,4 V) por debajo de 3,3 V: por ejemplo, 33 kΩ y 10 kΩ → 8,4 × 10/43 ≈ 1,95 V. El ADC del ESP32 no es muy lineal: calibra comparando con el multímetro.\n- **Distancia frontal:** HC-SR04 (con divisor en Echo para el ESP32) o VL53L0X.\n- **Velocidad:** con encoders (M13).\n- **Calidad del enlace:** paquetes perdidos (con el contador del paquete), o RSSI en WiFi (`WiFi.RSSI()`).",
   "### Cómo enviarla",
   "- **Bluetooth:** el carro envía cada medio segundo una línea de texto («B7.6;D42») que muchas apps muestran.\n- **WiFi:** en la respuesta JSON de cada orden (lección 3).\n- **nRF24L01:** en el *ACK payload*, que viaja de vuelta con cada acuse de recibo, o alternando los papeles de emisor y receptor.",
   "### Mostrarla",
   "En el mando: una pantalla **OLED** (M11) con la batería en porcentaje y una barra, la distancia y un indicador de señal. En la página web: textos, colores y una barra. Usa **alertas** claras: batería por debajo de 3,4 V por celda → aviso; por debajo de 3,2 V → el carro reduce la velocidad y pide volver.",
   "### Porcentaje de batería",
   "Una aproximación lineal para una batería 2S de litio: `% = (V − 6,4) / (8,4 − 6,4) × 100`, limitado a 0–100. No es exacta (la curva real de descarga no es lineal), pero es suficiente para avisar."],
  c: {l: "cpp", t: "// Telemetría del carro: batería (ESP32, divisor 33k/10k en GPIO35) y porcentaje\nfloat voltajeBateria() {\n  float v = analogRead(35) * 3.3 / 4095.0;       // voltaje en el pin\n  return v * (33.0 + 10.0) / 10.0 * 1.05;        // deshacer el divisor (+ ajuste de calibración)\n}\n\nint porcentajeBateria(float v) {                 // batería 2S de litio\n  return constrain((int)((v - 6.4) / (8.4 - 6.4) * 100), 0, 100);\n}\n\nunsigned long tTele = 0;\nvoid enviarTelemetria() {\n  if (millis() - tTele < 500) return;\n  tTele = millis();\n  float v = voltajeBateria();\n  SerialBT.printf(\"BAT %.1f V (%d %%)  DIST %d cm\\n\", v, porcentajeBateria(v), (int)distancia);\n  if (v < 6.8) SerialBT.println(\"¡Batería baja! Vuelve a la base\");\n}"},
  sg: "No descargues la batería de litio por debajo de unos 3 V por celda: usa la telemetría para parar a tiempo.",
  er: ["Medir el voltaje de la batería directamente con un pin de 3,3 V o 5 V sin divisor.", "Confiar en el ADC del ESP32 sin calibrar."],
  q: [["¿Qué es la telemetría?", ["Las órdenes del mando", "Los datos que el vehículo envía sobre su estado", "El chasis", "Un tipo de motor"], 1, "Batería, distancia, velocidad…"],
   ["Divisor de 33 kΩ arriba y 10 kΩ abajo con 8,4 V. ¿Voltaje en el pin? (en V)", {n: 1.95, tol: 0.02, u: "V"}, null, "8,4 × 10/43 ≈ 1,95 V."],
   ["Batería 2S a 7,4 V. ¿Porcentaje con la fórmula lineal? (en %)", {n: 50, tol: 0.02, u: "%"}, null, "(7,4 − 6,4)/(8,4 − 6,4) × 100 = 50 %."],
   ["¿Qué indica el contador del paquete por radio?", ["La batería", "Si se han perdido paquetes", "La velocidad", "La temperatura"], 1, "Si salta números, faltan paquetes."],
   ["¿Qué función da la intensidad de la señal WiFi en el ESP32?", ["WiFi.RSSI()", "analogRead()", "millis()", "tone()"], 0, "RSSI en dBm."]]},
 {t: "Seguridad: parada al perder la señal", h: 1, s: 1, p: "¿Qué hace tu carro si el móvil se queda sin batería mientras va a toda velocidad?",
  o: ["Implementar un sistema de parada segura (failsafe) por tiempo.", "Añadir freno automático ante obstáculos y otras protecciones."],
  x: ["En cualquier vehículo teleoperado, desde un juguete hasta un dron profesional, la pregunta clave es: **¿qué pasa si se pierde la comunicación?** La respuesta debe ser siempre un **estado seguro**: en un carro, **detenerse**. Esto se llama **failsafe** (fallo seguro).",
   "### El temporizador de órdenes (*watchdog*)",
   "- El mando envía órdenes (o latidos) de forma **continua**, varias veces por segundo, aunque no cambien.\n- El carro guarda el momento de la **última orden válida**.\n- Si pasa más de un tiempo límite (por ejemplo, **500 ms**) sin recibir nada, el carro **frena** y entra en un estado de «sin señal» (LED parpadeando). Cuando vuelve la señal, **no arranca solo**: espera una orden de velocidad 0 o una pulsación para evitar sorpresas.",
   "Elige el tiempo límite con cuidado: muy corto da paradas falsas por un paquete perdido; muy largo deja al carro sin control demasiado tiempo. Entre 300 y 700 ms es razonable.",
   "### Freno automático",
   "Aunque el conductor ordene avanzar, si el sensor frontal detecta un obstáculo a menos de, por ejemplo, 20 cm, el carro **limita la velocidad hacia delante** (y permite retroceder). Es un sistema de asistencia como el de los coches modernos.",
   "### Otras protecciones",
   "- **Botón o interruptor de emergencia** en el propio carro.\n- **Batería baja:** reducir la velocidad y avisar (lección 5).\n- **Arranque seguro:** los motores no se mueven hasta recibir la primera orden válida después del encendido.\n- **Watchdog del microcontrolador:** reinicia la placa si el programa se cuelga (`esp_task_wdt` en el ESP32, `wdt_enable` en el Arduino), útil en proyectos avanzados.",
   "Diseñar pensando en los fallos es lo que distingue un proyecto de aficionado de un sistema fiable."],
  c: {l: "cpp", t: "// Failsafe y freno automático\nconst unsigned long LIMITE = 500;   // ms sin órdenes\nbool sinSenal = true;               // arranque seguro: no se mueve hasta la primera orden\n\nvoid aplicarOrden(int avance, int giro) {\n  ultimaOrden = millis();\n  if (sinSenal && avance != 0) return;      // tras perder la señal, exige primero parar\n  sinSenal = false;\n  if (avance > 0 && distancia < 20) avance = 0;   // freno automático hacia delante\n  int izq = constrain(avance + giro, -100, 100), der = constrain(avance - giro, -100, 100);\n  mover(izq * 255 / 100, der * 255 / 100);\n}\n\nvoid vigilarSenal() {\n  if (!sinSenal && millis() - ultimaOrden > LIMITE) {\n    mover(0, 0);\n    sinSenal = true;\n  }\n  digitalWrite(LED_ESTADO, sinSenal ? (millis() / 250) % 2 : HIGH);   // parpadea sin señal\n}"},
  sg: "Prueba el failsafe con el carro en el aire antes de conducirlo: apaga el mando o cierra la página y comprueba que los motores se detienen.",
  er: ["Programar el carro para que siga con la última orden al perder la señal.", "Que el carro arranque solo al recuperar la señal."],
  q: [["¿Qué significa failsafe?", ["Que nunca falla", "Que ante un fallo pasa a un estado seguro", "Un tipo de batería", "Un protocolo de radio"], 1, "En un carro, detenerse."],
   ["¿Qué hace el carro si pasan más de 500 ms sin órdenes?", ["Acelera", "Se detiene", "Gira", "Se reinicia siempre"], 1, "Es el temporizador de órdenes."],
   ["¿Por qué no debe arrancar solo al recuperar la señal?", ["Para evitar movimientos inesperados", "Para ahorrar batería", "Porque no puede", "No importa"], 0, "Primero debe recibir una orden de parada."],
   ["Con un obstáculo a 15 cm y orden de avanzar, el freno automático…", ["Permite avanzar", "Impide avanzar pero deja retroceder", "Apaga el carro", "Hace girar"], 1, "Limita solo el avance."],
   ["¿Qué rango de tiempo límite es razonable para el failsafe?", ["5 ms", "300–700 ms", "10 s", "1 minuto"], 1, "Ni demasiado corto ni demasiado largo."]]}
 ]}
);
